using UnityEngine;
using UnityEngine.Rendering;

namespace Fire3D.Unity.Presentation
{
    /// <summary>Textures for the fire/smoke systems (Art/VFX, generated by Tools/VfxTextures).</summary>
    public sealed class VfxTextures
    {
        public Texture2D Flame;   // 8×8 flipbook, colour in RGB, heat in A.
        public Texture2D Smoke;   // 8×8 flipbook, shaded grey + alpha.
        public Texture2D Glow;    // soft radial dot.
        public Texture2D Haze;    // tileable RG distortion noise.
        public Shader HazeShader;
        public Texture2D SmokeLightA; // six-way lit smoke: R right, G top, B back, A transparency.
        public Texture2D SmokeLightB; // R left, G bottom, B front.
        public Shader SmokeShader;
    }

    /// <summary>
    /// Builds layered, mobile-friendly fire and smoke (Particle System, no VFX Graph): flipbook flames with frame
    /// blending, soft particles and camera fade, a hot core, ember streaks, a flickering ground glow and an optional
    /// refractive heat haze; lit flipbook smoke that the fire lights tint from below. Built into prefabs by the
    /// Editor; at runtime without prefabs it falls back to procedural dots.
    /// </summary>
    public static class VfxFactory
    {
        public const int FlipbookTiles = 8;
        public const string HazeLayer = "HeatHaze";

        public static ParticleSystem Create(bool fire, Transform parent, VfxTextures tex = null)
        {
            var root = new GameObject(fire ? "Flame" : "Smoke");
            root.transform.SetParent(parent, false);
            var ps = fire ? Flames(root, tex) : Smoke(root, tex);
            if (fire)
            {
                Core(root.transform, tex);
                Embers(root.transform, tex);
                Glow(root.transform, tex);
                if (tex?.HazeShader != null && tex.Haze != null)
                    Haze(root.transform, tex);
            }

            return ps;
        }

        // ---- Fire layers ---------------------------------------------------------------------------------------

        private static ParticleSystem Flames(GameObject go, VfxTextures tex)
        {
            var ps = NewSystem(go, 70, 0.6f, 1.05f);
            var main = ps.main;
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.5f, 1.1f);
            main.startSize = new ParticleSystem.MinMaxCurve(1.7f, 2.7f);
            main.startRotation = new ParticleSystem.MinMaxCurve(-12f * Mathf.Deg2Rad, 12f * Mathf.Deg2Rad);
            main.gravityModifier = -0.06f;
            var emission = ps.emission;
            emission.rateOverTime = 22f;
            Cone(ps, 0.28f, 6f, lift: 0.8f); // billboards are centred on the particle: lift so the base sits on the floor
            Flipbook(ps, tex?.Flame != null);
            Fade(ps, new Color(1f, 1f, 1f), new Color(1f, 0.82f, 0.62f), new Color(1f, 0.5f, 0.3f), 0.16f, 0.55f);
            Size(ps, 0.7f, 1f, 0.72f);
            Turbulence(ps, 0.22f, 1.1f);
            Render(go, Material(fire: true, tex?.Flame, additive: true, lit: false), tex?.Flame != null, 0.3f);
            return ps;
        }

        private static void Core(Transform parent, VfxTextures tex)
        {
            var go = Child("Core", parent);
            var ps = NewSystem(go, 30, 0.35f, 0.6f);
            var main = ps.main;
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.15f, 0.4f);
            main.startSize = new ParticleSystem.MinMaxCurve(1.0f, 1.6f);
            main.startColor = new Color(1f, 0.92f, 0.78f, 1f);
            var emission = ps.emission;
            emission.rateOverTime = 14f;
            Cone(ps, 0.18f, 4f, lift: 0.55f);
            Flipbook(ps, tex?.Flame != null);
            Fade(ps, Color.white, new Color(1f, 0.9f, 0.7f), new Color(1f, 0.6f, 0.35f), 0.12f, 0.45f);
            Size(ps, 0.8f, 1f, 0.6f);
            Render(go, Material(fire: true, tex?.Flame, additive: true, lit: false), tex?.Flame != null, 0.25f);
        }

        private static void Embers(Transform parent, VfxTextures tex)
        {
            // Sparks of every size drifting up and sideways for several seconds, like a campfire at night: a few big
            // slow ones, many tiny quick ones, all twinkling.
            var go = Child("Embers", parent);
            var ps = NewSystem(go, 90, 1.6f, 4.2f);
            var main = ps.main;
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.5f, 2.4f);
            main.startSize = new ParticleSystem.MinMaxCurve(0.012f, 0.07f);
            main.startColor = new ParticleSystem.MinMaxGradient(new Color(1f, 0.82f, 0.45f), new Color(1f, 0.42f, 0.1f));
            main.gravityModifier = -0.04f;
            var emission = ps.emission;
            emission.rateOverTime = 9f;
            Cone(ps, 0.4f, 24f);
            var col = ps.colorOverLifetime;
            col.enabled = true;
            var g = new Gradient();
            g.SetKeys(
                new[] { new GradientColorKey(new Color(1f, 0.9f, 0.6f), 0f), new GradientColorKey(new Color(1f, 0.5f, 0.15f), 0.5f), new GradientColorKey(new Color(0.7f, 0.15f, 0.04f), 1f) },
                new[] { new GradientAlphaKey(0f, 0f), new GradientAlphaKey(1f, 0.08f), new GradientAlphaKey(0.9f, 0.6f), new GradientAlphaKey(0f, 1f) });
            col.color = new ParticleSystem.MinMaxGradient(g);
            var size = ps.sizeOverLifetime;
            size.enabled = true;
            size.size = new ParticleSystem.MinMaxCurve(1f, new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(0.7f, 0.8f), new Keyframe(1f, 0.15f)));
            Turbulence(ps, 1.1f, 0.9f);
            var vel = ps.velocityOverLifetime;
            vel.enabled = true;
            vel.space = ParticleSystemSimulationSpace.World;
            vel.x = new ParticleSystem.MinMaxCurve(-0.25f, 0.45f); // a faint draught drifts them one way
            vel.y = new ParticleSystem.MinMaxCurve(0f, 0f); // all three axes must use the same curve mode
            vel.z = new ParticleSystem.MinMaxCurve(-0.15f, 0.15f);
            var r = Render(go, Material(fire: true, tex?.Glow, additive: true, lit: false, flipbook: false), false, 0f);
            r.renderMode = ParticleSystemRenderMode.Billboard;
            r.maxParticleSize = 0.06f;
        }

        private static void Glow(Transform parent, VfxTextures tex)
        {
            // Warm pool of light spilled on the floor around the fire (the yellow disc in a night campfire), plus a
            // faint upright halo. Flat quads sit just above the floor, so soft particles blend them into the surface.
            var floor = Child("FloorGlow", parent);
            floor.transform.localPosition = new Vector3(0f, 0.04f, 0f);
            var ps = NewSystem(floor, 6, 0.7f, 1.1f);
            var main = ps.main;
            main.startSpeed = 0f;
            main.startSize = new ParticleSystem.MinMaxCurve(3.4f, 4.4f);
            main.startColor = new Color(1f, 0.55f, 0.16f, 0.17f);
            var emission = ps.emission;
            emission.rateOverTime = 6f;
            var shape = ps.shape;
            shape.enabled = false;
            Fade(ps, Color.white, Color.white, Color.white, 0.3f, 0.5f);
            var fr = Render(floor, Material(fire: true, tex?.Glow, additive: true, lit: false, flipbook: false), false, 0.9f);
            fr.renderMode = ParticleSystemRenderMode.HorizontalBillboard;

            var halo = Child("Halo", parent);
            halo.transform.localPosition = new Vector3(0f, 0.5f, 0f);
            var hs = NewSystem(halo, 6, 0.5f, 0.8f);
            var hm = hs.main;
            hm.startSpeed = 0f;
            hm.startSize = new ParticleSystem.MinMaxCurve(1.5f, 2.0f);
            hm.startColor = new Color(1f, 0.5f, 0.14f, 0.2f);
            var he = hs.emission;
            he.rateOverTime = 6f;
            var hsh = hs.shape;
            hsh.enabled = false;
            Fade(hs, Color.white, Color.white, Color.white, 0.3f, 0.5f);
            Render(halo, Material(fire: true, tex?.Glow, additive: true, lit: false, flipbook: false), false, 0.6f);
        }

        private static void Haze(Transform parent, VfxTextures tex)
        {
            var go = Child(HazeLayer, parent);
            go.transform.localPosition = new Vector3(0f, 0.9f, 0f);
            var ps = NewSystem(go, 14, 1.4f, 2.2f);
            var main = ps.main;
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.5f, 0.9f);
            main.startSize = new ParticleSystem.MinMaxCurve(1.8f, 2.8f);
            main.startColor = new Color(1f, 1f, 1f, 0.9f);
            var emission = ps.emission;
            emission.rateOverTime = 6f;
            Cone(ps, 0.3f, 5f);
            Size(ps, 0.6f, 1f, 1.5f);
            Fade(ps, Color.white, Color.white, Color.white, 0.25f, 0.6f);
            var m = new Material(tex.HazeShader) { name = "HeatHaze" };
            m.SetTexture("_BaseMap", tex.Haze);
            m.SetFloat("_Strength", 0.022f);
            Render(go, m, false, 0f);
            go.SetActive(false); // FireQuality turns it on where the opaque texture is affordable.
        }

        // ---- Smoke ---------------------------------------------------------------------------------------------

        private static ParticleSystem Smoke(GameObject go, VfxTextures tex)
        {
            // Few big flipbook sprites (each one rolls inside itself) instead of thousands of small particles. Indoors a
            // sprite must stay smaller than the room: a quad wider than the corridor is cut straight by the walls and
            // the smoke reads as a black box. Black soot at the source, greying as it spreads and cools.
            // More, smaller puffs per emitter (rather than a few room-sized ones): the cloud's outline becomes the sum of
            // many curved edges, and nothing is wide enough to be sliced flat by a corridor wall.
            // Emission/shape are overridden by VolumeSmoke at runtime (it emits straight into smoky grid cells);
            // the values here only matter for the prefab preview.
            var ps = NewSystem(go, 1200, 4.5f, 7.5f);
            var main = ps.main;
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.1f, 0.3f);
            main.startSize = new ParticleSystem.MinMaxCurve(1.0f, 1.7f);
            main.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            main.startColor = new Color(0.8f, 0.78f, 0.76f, 1f);
            var emission = ps.emission;
            emission.rateOverTime = 8.5f;
            var shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = 0.85f;
            shape.radiusThickness = 1f;
            var rot = ps.rotationOverLifetime;
            rot.enabled = true;
            rot.z = new ParticleSystem.MinMaxCurve(-0.2f, 0.2f);
            Flipbook(ps, tex?.Smoke != null);
            // Neutral ramp: colour comes from VolumeSmoke per puff (fresh pale → aged soot); this only fades in/out.
            Fade(ps, Color.white, Color.white, Color.white, 0.22f, 0.62f, 0.5f);
            Size(ps, 0.55f, 1f, 1.35f);
            Turbulence(ps, 0.16f, 0.45f);
            var sixWay = tex?.SmokeShader != null && tex.SmokeLightA != null && tex.SmokeLightB != null;
            var material = sixWay ? SixWaySmokeMaterial(tex) : Material(fire: false, tex?.Smoke, additive: false, lit: true);
            Render(go, material, sixWay || tex?.Smoke != null, 0.6f);
            return ps;
        }

        private static Material SixWaySmokeMaterial(VfxTextures tex)
        {
            var m = new Material(tex.SmokeShader) { name = "SmokeSixWay", renderQueue = (int)RenderQueue.Transparent };
            m.SetTexture("_LightmapA", tex.SmokeLightA);
            m.SetTexture("_LightmapB", tex.SmokeLightB);
            m.SetColor("_BaseColor", Color.white);
            m.SetFloat("_LightGain", 0.75f);
            m.SetFloat("_Ambient", 1.2f);
            return m;
        }

        // ---- Building blocks -----------------------------------------------------------------------------------

        private static GameObject Child(string name, Transform parent)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            return go;
        }

        private static ParticleSystem NewSystem(GameObject go, int max, float lifeMin, float lifeMax)
        {
            var ps = go.AddComponent<ParticleSystem>();
            ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
            var main = ps.main;
            main.loop = true;
            main.prewarm = true; // Fire is already burning when an emitter is (re)assigned: no grow-in pop.
            main.playOnAwake = false;
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.scalingMode = ParticleSystemScalingMode.Hierarchy;
            main.maxParticles = max;
            main.startLifetime = new ParticleSystem.MinMaxCurve(lifeMin, lifeMax);
            main.startColor = Color.white;
            return ps;
        }

        private static void Cone(ParticleSystem ps, float radius, float angle, float lift = 0f)
        {
            var shape = ps.shape;
            shape.position = new Vector3(0f, 0f, lift); // rotated -90° about X: local +Z is world up
            shape.shapeType = ParticleSystemShapeType.Cone;
            shape.radius = radius;
            shape.angle = angle;
            shape.rotation = new Vector3(-90f, 0f, 0f);
        }

        private static void Flipbook(ParticleSystem ps, bool on)
        {
            if (!on)
                return;
            var tsa = ps.textureSheetAnimation;
            tsa.enabled = true;
            tsa.mode = ParticleSystemAnimationMode.Grid;
            tsa.numTilesX = FlipbookTiles;
            tsa.numTilesY = FlipbookTiles;
            tsa.animation = ParticleSystemAnimationType.WholeSheet;
            tsa.timeMode = ParticleSystemAnimationTimeMode.Lifetime;
            tsa.frameOverTime = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.Linear(0f, 0f, 1f, 1f));
            // Each particle starts somewhere else in the loop, so neighbours never look identical.
            tsa.startFrame = new ParticleSystem.MinMaxCurve(0f, FlipbookTiles * FlipbookTiles - 1);
            tsa.cycleCount = 1;
        }

        private static void Fade(ParticleSystem ps, Color a, Color b, Color c, float fadeIn, float holdUntil, float peakAlpha = 1f)
        {
            var col = ps.colorOverLifetime;
            col.enabled = true;
            var g = new Gradient();
            g.SetKeys(
                new[] { new GradientColorKey(a, 0f), new GradientColorKey(b, 0.45f), new GradientColorKey(c, 1f) },
                new[] { new GradientAlphaKey(0f, 0f), new GradientAlphaKey(peakAlpha, fadeIn), new GradientAlphaKey(peakAlpha * 0.85f, holdUntil), new GradientAlphaKey(0f, 1f) });
            col.color = new ParticleSystem.MinMaxGradient(g);
        }

        private static void Size(ParticleSystem ps, float start, float mid, float end)
        {
            var size = ps.sizeOverLifetime;
            size.enabled = true;
            size.size = new ParticleSystem.MinMaxCurve(1f, new AnimationCurve(new Keyframe(0f, start), new Keyframe(0.35f, mid), new Keyframe(1f, end)));
        }

        private static void Turbulence(ParticleSystem ps, float strength, float frequency)
        {
            var noise = ps.noise;
            noise.enabled = true;
            noise.strength = strength;
            noise.frequency = frequency;
            noise.scrollSpeed = 0.6f;
            noise.octaveCount = 1;
            noise.quality = ParticleSystemNoiseQuality.Low; // 1D-per-axis lookups: cheap enough for mobile.
            noise.damping = true;
        }

        private static ParticleSystemRenderer Render(GameObject go, Material m, bool flipbook, float sortFudge)
        {
            var r = go.GetComponent<ParticleSystemRenderer>();
            r.sharedMaterial = m;
            r.renderMode = ParticleSystemRenderMode.Billboard;
            r.shadowCastingMode = ShadowCastingMode.Off;
            r.receiveShadows = false;
            r.sortingFudge = sortFudge;
            r.minParticleSize = 0f;
            r.maxParticleSize = 2.5f;
            if (flipbook)
            {
                // Frame blending needs the next frame's UV and the blend factor per vertex.
                r.SetActiveVertexStreams(new System.Collections.Generic.List<ParticleSystemVertexStream>
                {
                    ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Normal, ParticleSystemVertexStream.Color,
                    ParticleSystemVertexStream.UV, ParticleSystemVertexStream.UV2, ParticleSystemVertexStream.AnimBlend,
                });
            }

            return r;
        }

        /// <summary>
        /// URP particle material: additive (fire) or alpha (smoke), optional flipbook blending, soft particles
        /// (fade where the quad meets floor/walls, needs the depth texture) and camera near fade.
        /// </summary>
        public static Material Material(bool fire, Texture2D texture, bool additive, bool lit, bool flipbook = true)
        {
            var shader = Shader.Find(lit ? "Universal Render Pipeline/Particles/Simple Lit" : "Universal Render Pipeline/Particles/Unlit")
                         ?? Shader.Find("Universal Render Pipeline/Particles/Unlit");
            var m = new Material(shader) { name = fire ? (texture != null ? "Fire_" + texture.name : "FireDots") : "SmokeFlipbook" };
            m.SetTexture("_BaseMap", texture != null ? texture : SoftDot());
            m.SetColor("_BaseColor", Color.white);
            m.SetFloat("_Surface", 1f);
            m.SetOverrideTag("RenderType", "Transparent");
            m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            if (additive)
            {
                m.SetFloat("_Blend", 2f);
                m.SetInt("_SrcBlend", (int)BlendMode.SrcAlpha);
                m.SetInt("_DstBlend", (int)BlendMode.One);
            }
            else
            {
                m.SetFloat("_Blend", 0f);
                m.SetInt("_SrcBlend", (int)BlendMode.SrcAlpha);
                m.SetInt("_DstBlend", (int)BlendMode.OneMinusSrcAlpha);
            }

            m.SetInt("_ZWrite", 0);
            m.SetFloat("_Cull", (float)CullMode.Off);
            if (flipbook && texture != null)
            {
                m.SetFloat("_FlipbookBlending", 1f);
                m.EnableKeyword("_FLIPBOOKBLENDING_ON");
            }

            const float softNear = 0f, softFar = 0.45f;
            m.SetFloat("_SoftParticlesEnabled", 1f);
            m.SetFloat("_SoftParticlesNearFadeDistance", softNear);
            m.SetFloat("_SoftParticlesFarFadeDistance", softFar);
            m.SetVector("_SoftParticleFadeParams", new Vector4(softNear, 1f / (softFar - softNear), 0f, 0f));
            m.EnableKeyword("_SOFTPARTICLES_ON");
            const float camNear = 0.25f, camFar = 0.9f;
            m.SetFloat("_CameraFadingEnabled", 1f);
            m.SetFloat("_CameraNearFadeDistance", camNear);
            m.SetFloat("_CameraFarFadeDistance", camFar);
            m.SetVector("_CameraFadeParams", new Vector4(camNear, 1f / (camFar - camNear), 0f, 0f));
            m.EnableKeyword("_FADING_ON");
            m.renderQueue = (int)RenderQueue.Transparent;
            return m;
        }

        private static Material _spray;

        /// <summary>Plain soft-dot particle material (water spray); cached.</summary>
        public static Material ParticleMaterial(bool fire) =>
            _spray != null ? _spray : _spray = Material(fire, null, additive: fire, lit: false, flipbook: false);

        private static Texture2D _dot;

        private static Texture2D SoftDot()
        {
            if (_dot != null)
                return _dot;
            const int n = 64;
            _dot = new Texture2D(n, n, TextureFormat.RGBA32, false) { wrapMode = TextureWrapMode.Clamp, name = "SoftDot" };
            for (var y = 0; y < n; y++)
            for (var x = 0; x < n; x++)
            {
                var d = Vector2.Distance(new Vector2(x, y), new Vector2(n / 2f, n / 2f)) / (n / 2f);
                var a = Mathf.Clamp01(1f - d);
                a = a * a * (3f - 2f * a);
                _dot.SetPixel(x, y, new Color(1f, 1f, 1f, a));
            }

            _dot.Apply();
            return _dot;
        }
    }
}
